from pathlib import Path
import subprocess,json,hashlib,array,math
D=Path(__file__).resolve().parent/'actual-av-no-navigation';reports=json.loads((D/'report.json').read_text());out=[]
for name,report in zip(['mouse1280','touch844'],reports):
 p=D/(name+'-actual-input-audio.mp4');meta=json.loads(subprocess.check_output(['ffprobe','-v','quiet','-show_streams','-show_format','-of','json',str(p)]));assert any(s['codec_type']=='audio'for s in meta['streams'])and any(s['codec_type']=='video'for s in meta['streams']);raw=subprocess.check_output(['ffmpeg','-v','error','-i',str(p),'-map','0:a:0','-f','f32le','-ac','1','-ar','12000','-']);a=array.array('f');a.frombytes(raw);rms=math.sqrt(sum(v*v for v in a)/len(a));assert rms>1e-5;audioDuration=float(next(s['duration']for s in meta['streams']if s['codec_type']=='audio'));videoDuration=float(next(s['duration']for s in meta['streams']if s['codec_type']=='video'));delay=report['estimatedAudioDelaySec'];out.append({'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'videoDurationSec':videoDuration,'audioDurationSec':audioDuration,'observedRunningBasedOffsetSec':delay,'alignedAudioEndMinusVideoEndSec':delay+audioDuration-videoDuration,'streams':[{'type':s['codec_type'],'codec':s['codec_name'],'start_time':s.get('start_time')}for s in meta['streams']],'actualDecodedAudioRms':rms,'audioStateEvents':report['audioContexts'],'alignment':'first actual AudioContext running/MediaRecorder start mapped to browser page clock; page creation/video origin estimated, not hardware synchronized or human AV-review certified'})
(D/'media.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
